CREATE TABLE IF NOT EXISTS account_security (user_id INTEGER PRIMARY KEY,disabled INTEGER NOT NULL DEFAULT 0,revoked_before BIGINT NOT NULL DEFAULT 0,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS security_events (id TEXT PRIMARY KEY,actor_id INTEGER NOT NULL,target_id INTEGER NOT NULL,action TEXT NOT NULL,note TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS report_source_artifacts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,user_id INTEGER NOT NULL,content_hash TEXT NOT NULL,storage_key TEXT NOT NULL,file_name TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_call_reconciliations(id TEXT PRIMARY KEY,actor_id INTEGER NOT NULL,evidence TEXT NOT NULL,input_tokens BIGINT NOT NULL,output_tokens BIGINT NOT NULL,cost_micros BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS report_deliveries(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,author_id INTEGER NOT NULL,reviewer_id INTEGER NOT NULL,content_hash TEXT NOT NULL,snapshot_json TEXT NOT NULL,contract_json TEXT NOT NULL,result_json TEXT NOT NULL,status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL,reviewed_at BIGINT NOT NULL DEFAULT 0);
